import base64, gzip, json, os, re

def run(**kwargs):
    src = kwargs.get("src") or "missions/duskyr.com/extractions/tgemo_full.txt"
    out_dir = kwargs.get("out_dir") or "missions/duskyr.com/extractions/tgemo_assets"
    html = open(src, "r", encoding="utf-8", errors="replace").read()
    m = re.search(r'<script type="__bundler/manifest">(.*?)</script>', html, re.S)
    if not m:
        return "ERROR: no __bundler/manifest found"
    try:
        manifest = json.loads(m.group(1))
    except Exception as e:
        return f"ERROR: manifest JSON parse failed: {e}"
    po = re.search(r'<script type="__bundler/page_order">(.*?)</script>', html, re.S)
    page_order = json.loads(po.group(1)) if po else []
    os.makedirs(out_dir, exist_ok=True)
    results = []
    for uuid, entry in manifest.items():
        try:
            data = base64.b64decode(entry.get("data", ""))
            if entry.get("compressed"):
                try:
                    data = gzip.decompress(data)
                except Exception:
                    pass
            mime = entry.get("mime", "bin")
            ext = {"text/html": "html", "application/javascript": "js", "text/javascript": "js",
                   "text/css": "css", "application/json": "json", "image/svg+xml": "svg"}.get(mime, "bin")
            name = f"{uuid[:8]}.{ext}"
            with open(os.path.join(out_dir, name), "wb") as f:
                f.write(data)
            results.append({"file": name, "mime": mime, "bytes": len(data), "page": uuid in page_order})
        except Exception as e:
            results.append({"uuid": uuid, "error": str(e)})
    return json.dumps({"assets": len(results), "pages": len(page_order), "out_dir": out_dir,
                       "detail": results}, indent=1)

