import re, os, json

def run(**kwargs):
    path = kwargs.get("path")
    if not path:
        return "ERROR: path required"
    pattern = kwargs.get("pattern")
    if not pattern:
        return "ERROR: pattern required"
    window = int(kwargs.get("window") or 120)
    max_matches = int(kwargs.get("max_matches") or 60)
    full = kwargs.get("full", False)
    if not os.path.isabs(path):
        path = os.path.join("missions", path)
    try:
        data = open(path, "r", encoding="utf-8", errors="replace").read()
    except Exception as e:
        return f"ERROR: {e}"
    flags = re.DOTALL if full else 0
    try:
        rx = re.compile(pattern, flags)
    except Exception as e:
        return f"ERROR: bad regex: {e}"
    out = []
    for i, m in enumerate(rx.finditer(data)):
        if i >= max_matches:
            out.append(f"... (truncated at {max_matches})")
            break
        s = max(0, m.start() - window)
        e = min(len(data), m.end() + window)
        out.append(f"[{i}] @{m.start()}: ...{data[s:e]}...")
    if not out:
        return "NO MATCHES"
    return "\n\n".join(out)

